INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-0099-5058-a545-081500c84f4c', 'other', 'Solar power at UMass Amherst', 'UMass Amherst generates electricity from about 10 megawatts of solar panels spread across campus: on the roofs of five buildings and on canopies over parking lots, plus a solar array on the university farm in South Deerfield.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-a3e3-5a43-b2b5-e59cf7e4c529', 'other', 'UMass Permaculture gardens', 'Permaculture is a way of designing gardens that work like natural ecosystems: layers of fruit trees, shrubs, perennials and ground cover that feed each other and need little outside input once they are established.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-a99c-510e-9ab4-5337af926cac', 'other', 'LEED certification', 'LEED (Leadership in Energy and Environmental Design) is the U.S. Green Building Council''s rating system for green buildings. A project earns points for energy and water efficiency, materials, indoor air quality and the site, and its total sets the level: Certified, Silver, Gold or Platinum.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-3ee5-5d8e-900e-21d2857b4660', 'other', 'Electric vehicle charging on campus', 'Several campus parking lots and the Campus Center Parking Garage have Level 2 chargers for electric cars, operated by ChargePoint and open to students, faculty, staff and visitors.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-2139-541b-84e2-64d6a00006d6', 'other', 'ValleyBike', 'ValleyBike is the Pioneer Valley''s regional electric-assist bike share, launched in June 2018 by UMass Amherst, the Pioneer Valley Planning Commission and several towns and cities, with five stations on campus at the start. Riders unlock a bike at one station and return it at another, which makes short trips across campus and into town possible without a car.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-a64b-5cab-bc45-817a39c68e5e', 'other', 'Green Grounds: campus landscape care', 'UMass Amherst holds a Gold-level Green Grounds Certification from Re:wild Your Campus. At least 90% of the campus''s managed grounds are cared for without synthetic pesticides or fertilizers, native plants are favored, landscape water use is kept down, and synthetic chemicals are being reduced on sports fields.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-d403-5613-ac5d-cdc267d69bfc', 'other', 'Central Heating Plant', 'The campus power and steam plant on Mullins Way, completed in 2009.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-7627-5296-a82f-50d84b41af5c', 'other', 'North Energy Exchange Center', 'The heart of the campus''s new low-carbon heating and cooling system in the engineering area of north campus.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-b111-5154-a3ce-5694f2f662e1', 'other', 'Computer Sciences Laboratories', 'A four-story, 94,300-square-foot addition to the east side of the Computer Science Building at 140 Governors Drive, completed in summer 2025 for the Manning College of Information and Computer Sciences.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-a096-503c-8167-440b503a6314', 'other', 'Sustainable Engineering Laboratories', 'A 78,000-square-foot laboratory building for the Riccio College of Engineering.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-42a9-5e98-b788-8bc789a14298', 'other', 'Crotty Hall', 'The home of the Department of Economics at 412 North Pleasant Street, at the southern gateway to campus, completed in fall 2016.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-0573-52f5-8d76-5a3aa5a69f40', 'other', 'John W. Olver Design Building', 'The 87,500-square-foot home of Architecture, Landscape Architecture and Regional Planning, and Building and Construction Technology, at 551 North Pleasant Street, completed in spring 2017.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-890c-588d-a000-830141144ade', 'other', 'Integrative Learning Center', 'A four-story classroom building in the center of campus, completed in August 2014, with about 2,000 classroom seats and space for departments including Communication, Journalism, Linguistics and Film Studies.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-225d-5297-a715-1c16b46613c8', 'other', 'Physical Sciences Building', 'A 95,000-square-foot research building at 690 North Pleasant Street, completed in spring 2018, with flexible labs and offices for physics, computational and synthetic chemistry research.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-dd6e-5f01-b7e1-fcb77ad4747c', 'other', 'Life Science Laboratories', 'A 310,000-square-foot research laboratory at 240 Thatcher Road, completed in fall 2013, shared by groups from across the sciences and engineering.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-8f1e-5676-b417-9ffe504ecd71', 'other', 'Old Chapel', 'Built in 1885 in the Richardsonian Romanesque style, the Old Chapel is the campus''s best-known historic building. It held a library, auditorium and classrooms, later the Minuteman Marching Band, and closed in 1996.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-099b-55f7-800e-011282714d86', 'other', 'South College', 'A red-brick building at the campus core, rebuilt in 1886 on the foundation of the original 1867 South College after a fire. Over the years it held dormitories, classrooms, labs, a weather observatory and a museum.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-a04c-5644-b998-3b58d8393e04', 'other', 'UMass Police Station', 'The 27,130-square-foot home of the UMass Police Department at 585 East Pleasant Street, completed in spring 2011, on the edge of campus.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-c182-59a0-bd7a-27a2f40479b0', 'other', 'Recreation Center', 'The 120,000-square-foot campus gym at 161 Commonwealth Avenue, opened in fall 2009, used by an estimated 2,500 students a day.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-3e9a-5678-b00d-8d2983468065', 'other', 'Kennedy Champions Center', 'The 55,000-square-foot practice and training home of the UMass men''s and women''s basketball teams at 190 Commonwealth Avenue, completed in summer 2015 and connected to the Mullins Center by an enclosed walkway.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-72b0-52cb-8ffc-a23f55cabfdc', 'other', 'Fine Arts Center', 'The arts complex at the south end of the Campus Pond, home to concert halls, galleries and studios.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-e82c-577e-9ed8-ced065f8a574', 'other', 'Computer Science Building', 'The original home of the Manning College of Information and Computer Sciences on Governors Drive. The Computer Sciences Laboratories (2025) is built onto its east side and connects to every floor.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-3098-567d-be6d-ecc0db4bebcb', 'other', 'Hampshire Dining Commons', 'A dining commons in the Southwest Residential Area, renovated in 2013 into an open, circular plan with 12 food stations and seats for 650.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-00aa-5b21-afc5-111699504ccd', 'other', 'Worcester Commons', 'An 87,000-square-foot dining and student life building at 667 North Pleasant Street, opened in fall 2020, with the campus bakery, a café, the dining commons (about 800 seats) and a restaurant.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-70ee-5492-83d8-4ece96a22044', 'other', 'New2U Thrift Store', 'A student-run thrift store in Hampden Commons (131 Southwest Circle) that sells clothing, furniture, lamps, electronics and more, much of it collected from students during spring move-out.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-74e0-50c6-8d5a-3c4da7c0266c', 'other', 'Durfee Conservatory', 'A greenhouse complex founded in 1867, among the oldest buildings on campus, with gardens outside where students read in good weather.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-0552-5f0d-ab2d-5d53272f846b', 'other', 'CNS Research and Education Greenhouse', 'Teaching and research greenhouses for the Plant, Soil, and Insect Sciences department of the College of Natural Sciences, completed in April 2011.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-23ab-5d1f-aac6-37a049250329', 'other', 'Robsham Visitor Center solar canopies', 'Solar panels on canopies over the parking lot at the Robsham Visitor Center, completed in 2016.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-444b-5e86-9146-6000f27ca66a', 'other', 'Solar canopies by the Fleet Garage', 'A long row of solar canopies over a parking lot on the west side of campus, beside the university Fleet Garage and north of the Mullins Center.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-116c-56ab-b662-765761963727', 'other', 'North campus solar canopies', 'Two long rows of solar canopies over a large parking lot north of the main campus.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-511c-5522-9d3b-72ab147dede1', 'other', 'Southwest solar canopies', 'A row of solar canopies over a parking lot at the south end of the Southwest Residential Area, one of the newer additions to campus solar.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-6298-578a-8442-99fc2d860bf4', 'other', 'Agrivoltaic solar array at the South Deerfield farm', 'A ground-mounted solar array at the UMass Crop and Animal Research and Education Farm in South Deerfield, north of campus, in place since 2010.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-26ee-5a4f-96cc-91645643437e', 'other', 'Solar charging station at the Haigis Mall bus stop', 'A solar-powered station at the Haigis Mall bus stop where you can charge a phone or laptop while you wait, day or night, from standard outlets and USB ports. It and a twin at the Skinner Hall bus stop were gifts from the Class of 2014.', 42.3871994, -72.5264768, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-e2eb-53d7-84f2-2a9852fc37d1', 'other', 'Franklin Dining Commons', 'A dining commons in the Central Residential Area, next to the first of the campus permaculture gardens.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-713a-5d43-b183-2849d7aeecc5', 'other', 'Berkshire Dining Commons', 'A dining commons in the Southwest Residential Area, with a permaculture garden beside it.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-c755-5719-8153-c174e4958ab4', 'other', 'Hillside Permaculture Garden', 'A permaculture garden planted in fall 2012 at Hillside, the Chancellor''s residence. It was planted with food plants from India, the home country of the chancellor at the time, and visitors to the house have been served meals made with what grows here.', 42.3915345, -72.5209644, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-58d8-5e10-8293-cd31ce2326db', 'other', 'Food for All Garden', 'A garden at the UMass Agricultural Learning Center north of campus, started in 2013 by the Stockbridge School of Agriculture, that grows food for the Amherst Survival Center and the Not Bread Alone community meal program.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-ef50-5f7a-a727-4b3daf1f564b', 'other', 'Campus Pond', 'The pond at the center of campus, between the Student Union, the Campus Center and the Fine Arts Center.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-da24-56b7-aedf-9a5a38379846', 'other', 'Southwest Concourse', 'The five-acre pedestrian heart of the Southwest Residential Area, among the residence towers and dining commons that house about 5,000 students, rebuilt in 2011.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-ee7a-5b30-8aa0-c389c8f6c0d4', 'other', 'Pollinator Garden', 'A garden made in 2016 by Landscape Management and students from the Stockbridge School of Agriculture, with plants chosen to attract bees, butterflies and hummingbirds, and a water source for them.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-23f1-51a5-ab42-bcaff73ed4f4', 'other', 'EV charging at the Campus Center Parking Garage', 'Level 2 electric vehicle chargers in the Campus Center Parking Garage, operated by ChargePoint and open to students, faculty, staff and visitors.', 42.391239, -72.5290819, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-9578-59bf-ade2-02409546bdc5', 'other', 'EV charging at the Robsham Visitor Center lot', 'Electric vehicle chargers in the visitor parking lot at the Robsham Visitor Center, the same lot covered by the campus''s first solar canopies.', 42.3850929, -72.5250292, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-3d34-58c0-8598-b71a1ea89846', 'other', 'Fleet EV charging at the Physical Plant', 'Charging stations for the university''s own electric fleet vehicles at the Physical Plant, installed with a $175,000 Massachusetts Department of Energy Resources grant as the campus fleet switches to electric.', 42.3929939, -72.5315866, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-810d-51fb-a184-d43716ac0ae0', 'other', 'ValleyBike station at Haigis Mall', 'A ValleyBike e-bike share station at Haigis Mall, beside the busiest bus stop on campus.', 42.3871017, -72.5267416, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-b6d1-5b82-b1db-669611eaf6dd', 'other', 'ValleyBike station at the Integrative Learning Center', 'A ValleyBike e-bike share station by the Integrative Learning Center, in the middle of campus.', 42.3914507, -72.5254522, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-de47-517b-b7c8-30bb815a6e89', 'other', 'ValleyBike station in Southwest', 'A ValleyBike e-bike share station in the Southwest Residential Area.', 42.3848957, -72.5309058, NULL, false)
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-060a-552a-8fd2-9f2c03783b2b', 'other', 'PVTA bus service', 'Free, frequent bus service for students, faculty and staff, run in partnership with the Pioneer Valley Transit Authority (PVTA) and connecting campus to the neighboring towns. Haigis Mall is the main campus stop.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-8512-5422-ae31-5a0125b8fe9f', 'other', 'Surplus Property Barn', 'A showroom where university departments pass on furniture and equipment they no longer need to other departments, rather than throwing it away.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-ea7b-5794-a7dc-1b58d93a8fab', 'other', 'Solar hot water at the Central Heating Plant', 'A solar hot water system added to the Central Heating Plant in 2016.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-7616-597c-83df-eb322e000101', 'other', 'Reclaimed water at the Central Heating Plant', 'Much of the water the Central Heating Plant turns into steam, and the water for its cooling towers, is not drinking water. It is reclaimed water from the Amherst Wastewater Treatment Plant, cleaned further by reverse osmosis before it goes into the boilers.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-0244-517b-96cc-a3b578977477', 'other', 'Rooftop courtyard and green roof', 'A public courtyard on the Design Building''s roof, finished in January 2017, planted with native species in soils of different depths and fitted with built-in seating.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-8ff7-517d-9384-c88fa25bde81', 'other', 'Design Building rain garden', 'A rain garden beside the Design Building that catches the water running off its roof and paving.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-ff86-5bd9-b989-74e35af4a3a5', 'other', 'Integrative Learning Center green roof', 'About 15,000 square feet of the Integrative Learning Center''s roof is planted with hardy, low-maintenance plants such as sedum instead of bare roofing.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-ab1d-505c-a7e3-492e81b3cc83', 'other', 'Integrative Learning Center stormwater landscape', 'The landscape around the Integrative Learning Center works with the existing slope of the site. Rain gardens catch surface runoff, the plantings are native and need little watering, and stormwater from the site is reused to irrigate them instead of drinking water. During construction, several trees were saved and moved rather than cut down.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-eeea-541e-818e-5c62b9353e6c', 'other', 'Life Science Laboratories rainwater cistern', 'An underground cistern under the Life Science Laboratories landscape that collects and stores up to 10,000 gallons of rainwater.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-8242-5438-9e18-e2ee6b9faa86', 'other', 'Franklin Permaculture Garden', 'The first UMass permaculture garden, planted in 2010 on what had been a lawn beside the Franklin Dining Commons.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-d852-5be7-92e9-de5fc3eae6fe', 'other', 'Berkshire Permaculture Garden', 'The second campus permaculture garden, paid for by a gift from the Class of 2012. In a year, a neglected patch beside the Berkshire Dining Commons became a garden with rich soil and many kinds of plants, where volunteers learn sheet mulching, bed preparation and low-maintenance growing.
INSERT INTO artifacts (id, kind, name, description, lat, lng, parent_id, is_topic) VALUES ('5eed0081-9747-573b-bb68-8bbca6f3a3b5', 'other', 'Lab plastic recycling pilot', 'A pilot with Polycarbin, a Massachusetts company, that recycles used pipette tip boxes from the Life Science Laboratories and the Integrated Sciences Building back into new lab plastics. Collection bins are on most floors of this building.
